/**
 * Lean governance type definitions for the wallet SDK.
 *
 * These mirror the full types from @infrix/client but include only
 * the fields the wallet needs to operate. This avoids a hard dependency
 * on @infrix/client while maintaining wire-format compatibility.
 */

/**
 * Intent priorities: exactly the words the node's admission accepts (infrix-schema
 * `intent.ValidIntentPriorities`); none stated means `normal`, any other word is
 * refused. Generated by `tools/sdkgen` from the `priorities` of
 * `goal-vocabulary.json` (written by infrix-core from the set its admission
 * validates) — the same region the full client carries, never hand-copied.
 */
// SDKGEN-BEGIN(intent_priority)
export const INTENT_PRIORITIES = [
  'high',
  'normal',
  'urgent',
] as const;
export type IntentPriority = (typeof INTENT_PRIORITIES)[number];
// SDKGEN-END(intent_priority)

export interface IntentGoal {
  type: string;
  sourceAssets?: Array<{ asset: string; amount: number }>;
  targetAssets?: Array<{ asset: string; amount: number }>;
  targetState?: { stateType: string; parameters: Record<string, string> };
  via?: string;
  customType?: string;
  customParams?: Record<string, unknown>;
  /** The priority the submitter declares; omitted means `normal`. Sent beside `goalType` as the top-level `priority` the submit doors read. */
  priority?: IntentPriority;
}

export interface IntentResult {
  intentId: string;
  status: string;
  planId?: string;
  outcomeId?: string;
  gasUsed?: number;
  error?: string;
}

export interface IntentSubmitOptions {
  /** Why the intent is submitted: the Gap 12 disclosure purpose both roots require. */
  purpose: string;
  /** The workflow instance the intent belongs to: the Gap 12 disclosure context both roots require. */
  workflowInstance: string;
  constraints?: Record<string, unknown>;
  preferences?: Record<string, unknown>;
  metadata?: Record<string, string>;
}

export interface ApprovalEnvelope {
  id: string;
  targetId: string;
  planHash: string;
  signerIdentity: string;
  createdAt: string;
  status: string;
}

export interface OutcomeRecord {
  id: string;
  planId: string;
  overallStatus: string;
  totalGasUsed: number;
  gasDrift: number;
}

/**
 * What `intent.evidence` (GET /v4/intents/{id}/evidence) answers: every member the route declares.
 * It is NOT an evidence bundle: the bundles are in `bundles`, each as the object registry holds it
 * (its `id` is the evidence id the evidence routes take, `fields.AnchorStatus` its anchor state).
 */
export interface IntentEvidenceAnswer {
  /** The evidence bundles linked to the intent, as the object registry holds them. */
  bundles: unknown[];
  count: number;
  /** The intent as the object registry holds it. */
  intent: unknown;
  intentId: string;
}
